object Solution {
  import scala.collection.mutable

  def removeInvalidParentheses(s: String): List[String] = {
    def isValid(str: String): Boolean = {
      var count = 0
      for (c <- str) {
        if (c == '(') count += 1
        else if (c == ')') {
          count -= 1
          if (count < 0) return false
        }
      }
      count == 0
    }

    val res = mutable.ListBuffer[String]()
    val visited = mutable.HashSet[String]()
    val queue = mutable.Queue[String]()

    queue.enqueue(s)
    visited.add(s)
    var found = false

    while (queue.nonEmpty && !found) {
      val levelSize = queue.size
      for (_ <- 0 until levelSize) {
        val cur = queue.dequeue()
        if (isValid(cur)) {
          res += cur
          found = true
        }
        if (!found) {
          for (i <- cur.indices) {
            if (cur(i) == '(' || cur(i) == ')') {
              val next = cur.substring(0, i) + cur.substring(i + 1)
              if (!visited.contains(next)) {
                queue.enqueue(next)
                visited.add(next)
              }
            }
          }
        }
      }
    }

    if (res.isEmpty) List("") else res.toList.distinct
  }
}

